function validate([n, rides]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 100000.';
  if (!Array.isArray(rides) || rides.length < 1 || rides.length > 30000) return 'rides needs 1 to 30000 entries.';
  for (const ride of rides) {
    if (!Array.isArray(ride) || ride.length !== 3 || !ride.every(Number.isInteger)) return 'Each ride is [start, end, tip].';
    const [start, end, tip] = ride;
    if (start < 1 || start >= end || end > n) return 'Each ride needs 1 <= start < end <= n.';
    if (tip < 1 || tip > 100000) return 'Each tip is between 1 and 100000.';
  }
  return null;
}

