function maxTaxiEarnings(n, rides) {
  const endingAt = Array.from({ length: n + 1 }, () => []);
  for (const [start, end, tip] of rides) {
    endingAt[end].push([start, end - start + tip]);
  }
  const dp = new Array(n + 1).fill(0);
  for (let point = 2; point <= n; point++) {
    dp[point] = dp[point - 1];
    for (const [start, earning] of endingAt[point]) {
      dp[point] = Math.max(dp[point], dp[start] + earning);
    }
  }
  return dp[n];
}

