function maxTaxiEarnings(n, rides) {
  // best[i]: the most you can earn if ride i (in order of start) is the first one you take.
  const order = rides.map(([s, e, t]) => ({ s, e, gain: e - s + t })).sort((a, b) => a.s - b.s);
  const best = new Array(order.length).fill(0);
  let answer = 0;
  for (let i = order.length - 1; i >= 0; i--) {
    let after = 0;
    for (let j = i + 1; j < order.length; j++) if (order[j].s >= order[i].e) after = Math.max(after, best[j]);
    best[i] = order[i].gain + after;
    answer = Math.max(answer, best[i]);
  }
  return answer;
}

