function generate(rand, size) {
  const large = size === 'large';
  const n = large ? (rand() < 0.5 ? 100000 : 2000 + Math.floor(rand() * 3000)) : 2 + Math.floor(rand() * 12);
  const m = large ? 2000 : 1 + Math.floor(rand() * 8);
  const maxTip = large ? 100000 : (rand() < 0.5 ? 5 : 30);
  // Short rides make long chains worthwhile; long rides force real choices.
  const reach = large ? (rand() < 0.5 ? 200 : n) : n;
  const rides = [];
  for (let k = 0; k < m; k++) {
    const start = 1 + Math.floor(rand() * (n - 1));
    const end = start + 1 + Math.floor(rand() * Math.min(reach, n - start));
    rides.push([start, end, 1 + Math.floor(rand() * maxTip)]);
  }
  return [n, rides];
}
